BEGIN;
CREATE FUNCTION pg_temp.require(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL: %',label; END IF;RAISE NOTICE 'PASS: %',label;END$$;
INSERT INTO public.employees(employee_number,display_name,active) VALUES('9998','Fixture Desk',true),('4567','Fixture Other',true);
INSERT INTO public.nwtb_delivery_roles(employee_number,role,active) VALUES('9998','ADMIN',true);
SELECT public.nwtb_add_delivery_driver('0123','Fixture New Driver','9998');
SELECT pg_temp.require((SELECT display_name='Fixture New Driver' AND active FROM public.employees WHERE employee_number='0123'),'Name, leading-zero employee number and active employee saved');
SELECT pg_temp.require((SELECT role='DRIVER' AND active AND updated_by='9998' FROM public.nwtb_delivery_roles WHERE employee_number='0123'),'New employee has active DRIVER role');
SELECT pg_temp.require((SELECT count(*)=1 FROM public.delivery_events WHERE event_type='DELIVERY_DRIVER_ADDED'),'Driver creation audited once');
SELECT public.nwtb_add_delivery_driver('0123','Fixture New Driver','9998');
SELECT pg_temp.require((SELECT count(*)=1 FROM public.delivery_events WHERE event_type='DELIVERY_DRIVER_ADDED'),'Safe retry does not duplicate driver or audit event');
DO $$BEGIN
 BEGIN PERFORM public.nwtb_add_delivery_driver('0123','Different Fixture Name','9998');RAISE EXCEPTION 'Expected duplicate rejection';EXCEPTION WHEN unique_violation THEN NULL;END;
 BEGIN PERFORM public.nwtb_add_delivery_driver('9998','Fixture Replacement','9998');RAISE EXCEPTION 'Expected reserved number rejection';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 BEGIN PERFORM public.nwtb_add_delivery_driver('123','Fixture Short Number','9998');RAISE EXCEPTION 'Expected 4-digit validation';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 BEGIN PERFORM public.nwtb_add_delivery_driver('1111','F','9998');RAISE EXCEPTION 'Expected name validation';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 BEGIN PERFORM public.nwtb_add_delivery_driver('2222','Fixture Actor','7777');RAISE EXCEPTION 'Expected inactive actor rejection';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
END$$;
SELECT pg_temp.require((SELECT display_name='Fixture New Driver' FROM public.employees WHERE employee_number='0123'),'Duplicate cannot overwrite existing name');
SELECT pg_temp.require((SELECT role='ADMIN' FROM public.nwtb_delivery_roles WHERE employee_number='9998'),'Delivery Desk administrator preserved');
UPDATE public.nwtb_system_control SET state='KILLED' WHERE id=1;
DO $$BEGIN BEGIN PERFORM public.nwtb_add_delivery_driver('3333','Fixture Locked','9998');RAISE EXCEPTION 'Expected system lock';EXCEPTION WHEN raise_exception THEN IF SQLERRM NOT LIKE '%locked%' THEN RAISE; END IF;END;END$$;
SELECT pg_temp.require(NOT EXISTS(SELECT 1 FROM public.employees WHERE employee_number='3333'),'System lock prevents new driver');
UPDATE public.nwtb_system_control SET state='RUNNING' WHERE id=1;
ALTER TABLE public.delivery_events ADD CONSTRAINT fixture_audit_failure CHECK(event_type<>'DELIVERY_DRIVER_ADDED') NOT VALID;
DO $$BEGIN BEGIN PERFORM public.nwtb_add_delivery_driver('5555','Fixture Rollback','9998');RAISE EXCEPTION 'Expected failed audit';EXCEPTION WHEN check_violation THEN NULL;END;END$$;
SELECT pg_temp.require(NOT EXISTS(SELECT 1 FROM public.employees WHERE employee_number='5555'),'Failed creation rolls employee back');
SELECT pg_temp.require(NOT EXISTS(SELECT 1 FROM public.nwtb_delivery_roles WHERE employee_number='5555'),'Failed creation rolls role back');
ALTER TABLE public.delivery_events DROP CONSTRAINT fixture_audit_failure;
SELECT pg_temp.require(NOT has_function_privilege('anon','public.nwtb_add_delivery_driver(text,text,text)','execute'),'Anonymous callers cannot add drivers');
SELECT pg_temp.require(NOT has_function_privilege('authenticated','public.nwtb_add_delivery_driver(text,text,text)','execute'),'Generic auth callers cannot add drivers');
SELECT pg_temp.require(has_function_privilege('service_role','public.nwtb_add_delivery_driver(text,text,text)','execute'),'Service role can register a verified Office request');
SELECT pg_temp.require(NOT has_table_privilege('anon','public.nwtb_driver_push_keys','select'),'VAPID private keys not exposed to anonymous clients');
SELECT pg_temp.require(NOT has_table_privilege('authenticated','public.nwtb_driver_push_keys','select'),'VAPID private keys not exposed to authenticated clients');
SELECT pg_temp.require(NOT has_table_privilege('anon','public.nwtb_driver_push_subscriptions','select'),'Phone subscriptions not exposed anonymously');
SELECT pg_temp.require(NOT has_table_privilege('authenticated','public.nwtb_driver_push_subscriptions','select'),'Phone subscriptions not exposed to generic auth');
SELECT pg_temp.require((SELECT relrowsecurity FROM pg_class WHERE oid='public.nwtb_driver_push_keys'::regclass),'Private key table uses RLS');
SELECT pg_temp.require((SELECT relrowsecurity FROM pg_class WHERE oid='public.nwtb_driver_push_subscriptions'::regclass),'Subscription table uses RLS');
INSERT INTO public.chat_sessions(token,employee_number) VALUES('00000000-0000-4000-8000-000000000123','0123');
INSERT INTO public.nwtb_driver_push_subscriptions(driver_employee_number,session_token,endpoint,p256dh,auth,page_path) VALUES('0123','00000000-0000-4000-8000-000000000123','https://fcm.googleapis.com/fcm/send/fixture',repeat('a',87),repeat('b',22),'/nwtb-route-creator/driver-live.html');
DELETE FROM public.chat_sessions WHERE token='00000000-0000-4000-8000-000000000123';
SELECT pg_temp.require(NOT EXISTS(SELECT 1 FROM public.nwtb_driver_push_subscriptions WHERE driver_employee_number='0123'),'Driver logout removes bound phone subscriptions');
SELECT pg_temp.require((SELECT count(*)=0 FROM public.delivery_routes WHERE driver_employee_number='0123'),'Adding driver creates no route');
SELECT pg_temp.require((SELECT count(*)=0 FROM public.chat_sessions WHERE employee_number='0123'),'Adding driver creates no Driver session');
ROLLBACK;
